<dl class="dl-horizontal"><dt>Lần hoàn tất thành công</dt><dd><?php echo $health['last_success_at_utc']?CHtml::encode($health['last_success_at_utc']):'Chưa có'; ?></dd><dt>Dispatch được bật</dt><dd><?php echo $health['worker_enabled']?'Có (trong cấu hình hiện tại)':'Không'; ?></dd><dt>Heartbeat ngừng cập nhật</dt><dd><?php echo (int)$health['stuck_runs']; ?> lượt chạy</dd>
